import { revalidateTag } from 'next/cache'

export async function triggerCatalogSync() {
  // Background job syncs from ERP/PIM - handles thousands of SKUs
  // Triggered by the Server Action, runs asynchronously
  revalidateTag('products')
}

export default async function AdminProductsPage() {
  const products = await getProducts()

  return (
    <div>
      <header>
        <h1>Product Catalog</h1>
        <form action={triggerCatalogSync}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>
      <main>
        <table>
          <thead>
            <tr>
              <th>SKU</th>
              <th>Name</th>
              <th>Price</th>
              <th>Inventory</th>
              <th>Status</th>
