                <td>{product.inventory}</td>
                <td>{product.available ? 'Available' : 'Unavailable'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </main>
    </div>
  )
}

async function getProducts() {
  const res = await fetch(`${process.env.DATA_URL || 'http://localhost:3000'}/api/products`, {
    next: { tags: ['products'] },
  })
  return res.json()
}

