  revalidateTag('products')
}

interface Product {
  sku: string
  name: string
  price: number
  inventory: number
  available: boolean
}

function ProductRow({ product }: { product: Product }) {
  return (
    <tr>
      <td>{product.sku}</td>
      <td>{product.name}</td>
      <td>${product.price.toFixed(2)}</td>
      <td>{product.inventory}</td>
