  const products = await getProducts()

  return (
    <div>
      <header>
        <h1>Product Catalog</h1>
        <form action={triggerCatalogSync}>
          <button type="submit">Sync latest catalog</button>
        </form>
      </header>
      <main>
        <table>
          <thead>
            <tr>
              <th>SKU</th>
              <th>Name</th>
              <th>Price</th>
              <th>Inventory</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {products.map((product: Product) => (
              <ProductRow key={product.sku} product={product} />
            ))}
          </tbody>
        </table>
      </main>
    </div>
  )
}

